<?php
/** Painel Slides integrado: catálogo, editor acessível, mídia pública, associações, publicação e recuperação. */
declare(strict_types=1);
use CMS2JSON\{SlidesStore,Slides,Plugins,Icons,Security,HttpError};
use function CMS2JSON\{e,asset};
/** Traduz controles administrativos; recebe chave/parâmetros e retorna texto simples sem efeitos. */
$t=static fn(string $key,array $parameters=[]): string=>$context->language->text('slides.'.$key,$parameters);
/** Resolve rota privada; recebe rota/ID e retorna URL local sem escrita. */
$url=static fn(string $route,string $id=''): string=>$context->base.'/cms-admin/?view=plugin-panel&plugin=slides&route='.$route.($id!==''?'&id='.rawurlencode($id):'');
$repository=new SlidesStore($context->store);$snapshot=$repository->read();$data=$snapshot['data'];$revision=$snapshot['revision'];$csrf=Security::token();$route=$context->route;
$templates=$context->store->templates->all();$id=$_GET['id']??'';
if(!is_string($id)||($id!==''&&!SlidesStore::identifier($id)))throw new HttpError(404,'Conjunto inválido.','slides.error.missing');
$editing=$data['collections'][$id]??['id'=>'','name'=>'','contentType'=>'banner','status'=>'draft','deleted'=>false,'autoplay'=>false,'interval'=>6000,'items'=>[]];
if($route==='editor'&&$id!==''&&(!isset($data['collections'][$id])||$editing['deleted']))throw new HttpError(404,'Conjunto indisponível.','slides.error.missing');
$registry=new Plugins($context->store);$mediaState=isset($registry->all()['files-manager'])?$registry->state('files-manager'):['enabled'=>false,'settings'=>[]];
$mediaApi=$context->base.'/cms-admin/?view=plugin-api&plugin=files-manager&route=overview&operation=list&scope=public';
$issues=[];$missingMedia=[];
foreach($data['assignments'] as $binding){try{Slides::binding($context->store,$data,$binding);}catch(HttpError $error){if(!in_array($error->status,[404,422],true))throw $error;$issues[]=$binding['template'].' / '.$binding['location'];}}
$resolver=new Slides($context->store,'essencial');
foreach($data['collections'] as $set)if(!$set['deleted'])foreach($set['items'] as $item)if($item['image']!==''&&!$resolver->imageExists($item['image']))$missingMedia[]=$set['name'].' / '.$item['title'];
?>
<?php if(!$context->integrated): ?><!doctype html><html lang="<?= e($context->language->locale()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($t('name')) ?></title><link rel="stylesheet" href="<?= e(asset('cms-admin/assets/admin.css',$context->base)) ?>"><script defer src="<?= e(asset('cms-admin/assets/admin.js',$context->base)) ?>"></script><link rel="stylesheet" href="<?= e(asset('plugins/slides/css/slides.css',$context->base)) ?>"><script src="<?= e(asset('plugins/slides/js/slides.js',$context->base)) ?>" defer></script></head><body class="plugin-standalone plugin-content"><?php endif; ?>
<div class="slides-plugin" data-slides-plugin data-network-error="<?= e($t('network')) ?>">
<p class="notice error" role="alert" data-slides-status hidden></p>
<?php if($issues!==[]): ?><p class="notice" role="status"><?= e($t('issues',['items'=>implode(', ',array_unique($issues))])) ?></p><?php endif; ?>
<?php if($missingMedia!==[]): ?><p class="notice" role="status"><?= e($t('missingMedia',['items'=>implode(', ',array_unique($missingMedia))])) ?></p><?php endif; ?>
<?php if ($route==='overview'): $activeId=$context->store->read('site')['data']['template'];$activeLocations=Slides::locations($context->store->templates->get($activeId));$stale=[];foreach($data['assignments'] as $binding)if(!isset($activeLocations[$binding['location']]))$stale[]=$binding['template'].' / '.$binding['location'];if($stale!==[]): ?><p class="notice" role="status"><?= e($t('placementWarning',['items'=>implode(', ',array_unique($stale))])) ?></p><?php endif;endif; ?>
<?php if(in_array($route,['overview','trash'],true)): $rows=array_filter($data['collections'],static fn(array $set): bool=>$set['deleted']===($route==='trash')); ?>
<?php if($route==='overview'): ?><p><a class="button-primary" href="<?= e($url('editor')) ?>"><?= e($t('new')) ?></a></p><?php endif; ?>
<section class="panel extension-panel"><div class="table-scroll"><table class="extension-table"><caption class="sr-only"><?= e($t($route)) ?></caption><thead><tr><?php foreach(['nameColumn','contentType','items','status','actions'] as $column): ?><th scope="col"><?= e($t($column)) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach($rows as $set): ?><tr data-slides-id="<?= e($set['id']) ?>"><td data-label="<?= e($t('nameColumn')) ?>"><strong><?= e($set['name']) ?></strong><small class="extension-id"><?= e($set['id']) ?></small></td><td data-label="<?= e($t('contentType')) ?>"><?= e($t($set['contentType'])) ?></td><td data-label="<?= e($t('items')) ?>"><?= count($set['items']) ?></td><td data-label="<?= e($t('status')) ?>"><span class="status <?= $set['deleted']?'draft':$set['status'] ?>"><?= e($t($set['deleted']?'deleted':$set['status'])) ?></span></td><td data-label="<?= e($t('actions')) ?>"><div class="row-actions">
<?php if(!$set['deleted']): ?><a class="icon-button" href="<?= e($url('editor',$set['id'])) ?>" title="<?= e($t('edit')) ?>" aria-label="<?= e($t('edit')) ?>"><?= Icons::svg('edit',$context->base) ?></a><?php endif; ?>
<form method="post" action="<?= e($context->url($set['deleted']?'recover':'trash')) ?>" data-slides-form <?= !$set['deleted']?'data-confirm="'.e($t('confirmDelete')).'"':'' ?>><input type="hidden" name="revision" value="<?= e($revision) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($set['id']) ?>"><button class="icon-button" type="submit" title="<?= e($t($set['deleted']?'recover':'delete')) ?>" aria-label="<?= e($t($set['deleted']?'recover':'delete')) ?>"><?= Icons::svg($set['deleted']?'history':'uninstall',$context->base) ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php if($rows===[]): ?><p class="empty-state"><?= e($t($route==='trash'?'emptyTrash':'empty')) ?></p><?php endif; ?></section>
<?php elseif($route==='editor'): ?>
<form method="post" action="<?= e($context->url('save')) ?>" data-slides-form data-slides-editor data-state="<?= e(json_encode($editing['items'],JSON_THROW_ON_ERROR)) ?>" data-messages="<?= e(json_encode($context->language->messages(),JSON_THROW_ON_ERROR)) ?>" data-media-api="<?= e($mediaState['enabled']?$mediaApi:'') ?>" data-media-root="<?= e($mediaState['settings']['uploads']['public']??'') ?>" data-base="<?= e($context->base) ?>">
<input type="hidden" name="revision" value="<?= e($revision) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="original" value="<?= e($id) ?>"><input type="hidden" name="items" value="<?= e(json_encode($editing['items'],JSON_THROW_ON_ERROR)) ?>">
<section class="panel"><div class="field-grid"><label><?= e($t('collectionName')) ?><input name="name" maxlength="160" value="<?= e($editing['name']) ?>" required></label><label><?= e($t('id')) ?><input name="id" pattern="[a-z][a-z0-9\-]{0,47}" maxlength="48" value="<?= e($id) ?>" required <?= $id!==''?'readonly':'' ?>></label><label><?= e($t('contentType')) ?><select name="contentType" aria-label="<?= e($t('contentType')) ?>"><?php foreach(SlidesStore::CONTENT_TYPES as $type): ?><option value="<?= e($type) ?>" <?= $editing['contentType']===$type?'selected':'' ?>><?= e($t($type)) ?></option><?php endforeach; ?></select></label><label><?= e($t('status')) ?><select name="status" aria-label="<?= e($t('status')) ?>"><?php foreach(['draft','published'] as $status): ?><option value="<?= e($status) ?>" <?= $editing['status']===$status?'selected':'' ?>><?= e($t($status)) ?></option><?php endforeach; ?></select></label><label><?= e($t('interval')) ?><input name="interval" type="number" min="3000" max="30000" step="1" value="<?= e($editing['interval']) ?>" required></label><label class="slides-checkbox"><input type="checkbox" name="autoplay" value="1" <?= $editing['autoplay']?'checked':'' ?>><?= e($t('autoplay')) ?></label></div><p class="muted"><?= e($t('autoplayHelp')) ?></p></section>
<?php require __DIR__.'/placement.php'; ?>
<section class="panel"><div class="section-heading"><h2><?= e($t('items')) ?></h2><button type="button" class="button-secondary" data-add-slide><?= e($t('add')) ?></button></div><div data-slide-items></div><noscript><?= e($t('requiresJS')) ?></noscript></section>
<div class="savebar"><a class="text-link" href="<?= e($url('overview')) ?>"><?= e($t('overview')) ?></a><button type="submit" class="button-primary"><?= e($t('save')) ?></button></div></form>
<dialog data-slide-media aria-labelledby="slides-media-title"><div class="section-heading"><h2 id="slides-media-title"><?= e($t('mediaTitle')) ?></h2><button type="button" class="button-secondary" data-media-close><?= e($t('close')) ?></button></div><p><?= e($t('mediaHelp')) ?></p><div class="slides-media-toolbar"><button type="button" class="button-secondary" data-media-back><?= e($t('back')) ?></button><button type="button" class="button-secondary" data-media-refresh><?= e($t('refresh')) ?></button><span data-media-path></span><a class="text-link" href="<?= e($context->base.'/cms-admin/?view=plugin-panel&plugin=files-manager&route=overview') ?>" target="_blank" rel="noopener"><?= e($t('manageMedia')) ?></a></div><p role="status" data-media-status></p><div data-media-list></div></dialog>
<?php elseif ($route==='history'): ?>
<?php $historyEnabled=(new \CMS2JSON\Plugins($context->store))->state('slides')['enabled']; ?>
<?php if (!$historyEnabled): ?><p class="notice" role="status"><?= e($t('historyInactive')) ?></p><?php endif; ?>
<section class="panel"><h2><?= e($t('contentHistory')) ?></h2><?php if($repository->history()===[]): ?><p class="empty-state"><?= e($t('noHistory')) ?></p><?php endif; ?><?php foreach($repository->history() as $backup): ?><form class="history-row" method="post" action="<?= e($context->url('history-restore')) ?>" data-slides-form data-confirm="<?= e($t('confirmHistory')) ?>"><span><?= e(substr($backup,0,15)) ?></span><input type="hidden" name="revision" value="<?= e($revision) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="backup" value="<?= e($backup) ?>"><button class="button-secondary" type="submit" <?= !$historyEnabled?'disabled':'' ?>><?= e($t('restoreHistory')) ?></button></form><?php endforeach; ?></section>
<?php endif; ?></div>
<?php if(!$context->integrated): ?></body></html><?php endif; ?>
